import (
    "context"
    "sync/atomic"
    "time"
)

func main() {
    ctx, cancel := context.WithCancel(context.Background())
    defer cancel()

    pool := NewPool(4, 10)
    pool.Start(ctx)

    var counter int64
    for i := 0; i < 5; i++ {
        ok := pool.Submit(func(c context.Context) error {
            atomic.AddInt64(&counter, 1)
            return nil
        })
        if !ok {
            panic("failed to submit task")
        }
    }

    time.Sleep(50 * time.Millisecond)
    pool.Stop()

    if atomic.LoadInt64(&counter) != 5 {
        panic("task count mismatch")
    }
    println("Go Worker Pool Test Passed!")
}
